content.content:
.sidenav {
  background: var(--sidebar-bg);
  border-right: 1px solid var(--sidebar-border);
  transition: all 0.5s ease;
  position: fixed;
  z-index: 20;
  top: 0;
  left: 0;
  width: 4rem;
  height: 100vh;

  .logo-container {
    padding: 3px;
    overflow: hidden;
    white-space: nowrap;
    width: 100%;

    .logo-image {
      cursor: pointer;
      position: sticky;
      margin-top: 10px;
    }

    .logo-text {
      font-size: 21px;
      font-weight: 600;
      color: var(--theme-color);
      font-family: 'Calibri', sans-serif;
    }
  }
}

.sidenav-collapsed {
  width: 14.5625rem;
}

.sidenav-nav {
  list-style: none;
  padding: 0.6rem;
  margin: 0;
  display: flex;
  flex-direction: column;
  align-items: center;
  cursor: pointer;

  .sidenav-nav-item {
    width: 100%;
    margin-bottom: 0.2rem;

    .sidenav-nav-link {
      display: flex;
      align-items: center;
      height: 2rem;
      color: var(--text-main);
      text-decoration: none;
      font-size: 14px;
      font-weight: 500;
      font-family: 'Calibri', sans-serif;
      border-radius: 6px;
      transition: background 0.2s ease;

      .sidenav-link-icon {
        font-size: 16px;
        width: 2.6rem;
        min-width: 2.6rem;
        text-align: center;
        color: var(--accent);
      }

      .sidenav-link-text {
        margin-left: 0.2rem;
        text-overflow: ellipsis;
        overflow: hidden;
        white-space: nowrap;
        flex-grow: 1;
        color: inherit;
      }
    }

    .sidenav-nav-link:hover {
      background-color: var(--accent);
      color: #fff;

      .sidenav-link-icon,
      .sidenav-link-text,
      .menu-collapse-icon {
        color: #fff !important;
      }
    }
  }
}

/* ============ ACTIVE STATES (FIXED) ============ */
.sidenav-nav-link.active-sublevel,
a.sidenav-nav-link.active-sublevel {
  background-color: var(--accent);
  color: #fff !important;
  font-weight: 700;

  .sidenav-link-icon,
  .sidenav-link-text,
  .menu-collapse-icon {
    color: #fff !important;
  }
}

.sidenav-nav-link.active-parent {
  background-color: var(--accent-soft);
  color: var(--accent-dark) !important;
  font-weight: 700;

  .sidenav-link-icon,
  .sidenav-link-text,
  .menu-collapse-icon {
    color: var(--accent-dark) !important;
  }
}

.menu-collapse-icon {
  font-size: 15px;
  width: 2rem;
  min-width: 2rem;
  margin: auto 0.5rem auto auto;
  text-align: center;
  color: var(--text-main);
}

/* ============ SUBLEVEL NAV ============ */
.sublevel-nav {
  list-style: none;
  margin-left: 12px;
  margin-top: 5px;

  .sublevel-nav-item {
    .sublevel-nav-link {
      display: flex;
      align-items: center;
      height: 2rem;
      color: var(--text-main);
      text-decoration: none;
      width: 100%;
      border-radius: 6px;

      .sublevel-link-icon {
        font-size: 16px;
        width: 2.6rem;
        min-width: 2.6rem;
        text-align: center;
        color: var(--accent);
      }

      .sublevel-link-text {
        font-size: 13px;
        margin-left: 0.2rem;
        overflow: hidden;
        text-overflow: ellipsis;
        color: inherit;
      }
    }

    .sublevel-nav-link:hover {
      background-color: var(--accent);
      color: #fff;

      .sublevel-link-icon,
      .sublevel-link-text {
        color: #fff !important;
      }
    }
  }
}

.sublevel-nav-link.active-sublevel {
  background-color: var(--accent);
  color: #fff !important;
  font-weight: 700;
  border-left: 3px solid var(--accent-dark);

  .sublevel-link-icon,
  .sublevel-link-text {
    color: #fff !important;
  }
}

.sublevel-nav-link.active-parent {
  background-color: var(--accent-soft);
  color: var(--accent-dark) !important;
  font-weight: 700;

  .sublevel-link-icon,
  .sublevel-link-text {
    color: var(--accent-dark) !important;
  }
}

/* ============ SCROLL ============ */
.scrollwrap {
  overflow-x: hidden;
  overflow-y: auto;
  height: calc(100% - 5.65rem);
}

.sidenav-nav,
.scrollwrap:hover,
.scrollwrap:focus {
  visibility: visible;
}

.scrollwrap_delayed {
  transition: visibility 0.5s 0.2s;
}

.scrollwrap_delayed:hover {
  transition: visibility 0.2s 0.2s;
}

.scrollwrap::-webkit-scrollbar {
  width: 0;
}

.scrollwrap {
  scrollbar-width: none;
  -ms-overflow-style: none;
}

/* ============ HEADER ============ */
.head {
  width: calc(100% - 4rem);
  margin-left: 4rem;
  z-index: 15;
  transition: all 0.5s ease;
  position: fixed;
  top: 0;
  left: 0;

  .head-content {
    background-color: var(--header-bg);
    border-bottom: 1px solid var(--header-border);
    box-shadow: 0 1px 4px rgba(15, 23, 42, 0.04);
    min-height: 48px;
    padding: 0.5rem 1rem;

    > .d-flex {
      width: 100%;
      min-height: 40px;
    }
  }
}

.head-trimmed {
  width: calc(100% - 14.5625rem);
  margin-left: 14.5625rem;
}

.head-content h4 {
  margin: 0;
  font-size: 1rem;
}

.user-name {
  font-weight: 600;
  font-size: 16px;
  font-family: 'Calibri', sans-serif;
  color: var(--text-main);
}

.fa-bars,
.fa-power-off {
  cursor: pointer;
  padding: 0.5rem;
  font-size: 1.25rem;
}

hr {
  padding: 0;
  margin: 0;
}

.sidenav-heading {
  color: var(--text-soft);
  font-size: 18px;
  padding: 10px;
  text-overflow: ellipsis;
  overflow: hidden;
  white-space: nowrap;
}

.headLable {
  text-overflow: ellipsis;
  overflow: hidden;
  white-space: nowrap;
  flex-grow: 1;
}

@media screen and (max-width: 768px) {
  .sidenav,
  .sidenav-collapsed {
    width: 4rem;
  }

  .head,
  .head-trimmed {
    width: calc(100% - 4rem);
    margin-left: 4rem;
  }

  .head .head-content {
    padding: 0.25rem 0.5rem;
  }

  .user-name {
    display: none;
  }
}

@media screen and (max-width: 480px) {
  .head .head-content {
    min-height: 46px;
  }

  .notification-panel {
    width: 240px !important;
    right: -10px !important;
  }
}

