import { Injectable } from '@angular/core';
import { BreakpointObserver } from '@angular/cdk/layout';
import { BehaviorSubject, Observable, distinctUntilChanged, map } from 'rxjs';

/** Phones. Below this the sidebar leaves the layout entirely and opens as a drawer. */
const MOBILE_QUERY = '(max-width: 767.98px)';
/** Tablets. The rail stays put, but expanding it overlays the content instead of pushing it. */
const TABLET_QUERY = '(min-width: 768px) and (max-width: 1023.98px)';

export interface LayoutState {
  isMobile: boolean;
  isTablet: boolean;
  /** Mobile or tablet: the expanded nav floats above the content rather than shifting it. */
  isOverlay: boolean;
}

/**
 * The one place that decides which layout mode the shell is in.
 *
 * The shell is three sibling components (sidenav, body, footer) that each need the same
 * answer, so instead of passing `screenWidth` down through inputs this publishes the mode
 * on <body> as a class. CSS reads it from there through :host-context() and owns every
 * width and offset; TypeScript only says which mode we are in and whether the drawer is open.
 */
@Injectable({ providedIn: 'root' })
export class LayoutService {
  private readonly state = new BehaviorSubject<LayoutState>({
    isMobile: false,
    isTablet: false,
    isOverlay: false,
  });
  private readonly drawer = new BehaviorSubject<boolean>(false);

  readonly state$: Observable<LayoutState> = this.state.asObservable();
  readonly isMobile$: Observable<boolean> = this.state$.pipe(
    map((state) => state.isMobile),
    distinctUntilChanged(),
  );
  readonly isOverlay$: Observable<boolean> = this.state$.pipe(
    map((state) => state.isOverlay),
    distinctUntilChanged(),
  );
  readonly drawerOpen$: Observable<boolean> = this.drawer.asObservable();

  constructor(private breakpointObserver: BreakpointObserver) {
    this.breakpointObserver.observe([MOBILE_QUERY, TABLET_QUERY]).subscribe((result) => {
      const isMobile = result.breakpoints[MOBILE_QUERY];
      const isTablet = result.breakpoints[TABLET_QUERY];
      this.state.next({ isMobile, isTablet, isOverlay: isMobile || isTablet });

      // Rotating a tablet into desktop width must not leave a drawer open over the content.
