cat >> src/styles.scss <<'EOF'

/* ============================================================
   RESPONSIVE SHELL GEOMETRY
   One source of truth for the fixed chrome. The sidenav, body and
   footer read these instead of each repeating 4rem / 14.5625rem /
   48px / 40px, so a breakpoint only has to redefine them once.
   ============================================================ */
:root {
  --sidebar-w: 4rem;
  --sidebar-w-open: 14.5625rem;
  /* Phone drawer: wide enough for menu labels, never the whole screen. */
  --drawer-w: min(82vw, 17.5rem);
  --header-h: 48px;
  --footer-h: 40px;
  --shell-ease: 0.25s ease;
}

/* The footer is dropped on phones: 40px of copyright is a lot of a 640px screen. */
@media screen and (max-width: 767.98px) {
  :root {
    --footer-h: 0px;
  }
}

/* While the drawer is open it owns the screen; stop the page behind it scrolling. */
body.app-mobile.app-nav-open {
  overflow: hidden;
}

@media (prefers-reduced-motion: reduce) {
  .sidenav,
  .head,
  .body,
  .footer,
  .nav-scrim {
    transition: none !important;
  }
}
