    showPageSizeSelector: true,
    allowedPageSizes: [5, 10, 20, 50],
    showInfo: true,
    showNavigationButtons: true,
  };
  selectionConfig: Record<string, unknown> = { mode: 'multiple' };
  stateStoringConfig: Record<string, unknown> = {};

  private readonly breakpoints = new Subscription();

  private applyBreakpoint(isMobile: boolean, isOverlay: boolean): void {
    this.mobileMode = isMobile;
    this.adaptive = isOverlay;

    // Column resizing has to go for adaptive hiding to work at all: DevExtreme returns an
    // empty hiding queue - ignoring both columnHidingEnabled and hidingPriority - whenever
    // allowColumnResizing is on with columnResizingMode 'widget'. On touch it also turns an
    // ordinary list scroll into an accidental column drag, so it is no loss here.
    this.allowColumnResizing = !isOverlay;
    this.allowColumnReordering = !isOverlay;

    // Without a floor, columnAutoWidth + wordWrapEnabled shrink and wrap columns down to
    // slivers instead of ever letting one drop out.
    this.gridColumnMinWidth = isOverlay ? ADAPTIVE_MIN_WIDTH : undefined;

    this.filterRowConfig = { visible: !isMobile };
    this.searchPanelConfig = {
      visible: true,
      width: isMobile ? undefined : 240,
      placeholder: 'Search...',
    };
    this.pagerConfig = isMobile
      ? { showPageSizeSelector: false, showInfo: false, showNavigationButtons: true }
      : {
          showPageSizeSelector: true,
          allowedPageSizes: [5, 10, 20, 50],
          showInfo: true,
          showNavigationButtons: true,
        };
    this.selectionConfig = { mode: isMobile ? 'none' : this.selectionMode };
    this.stateStoringConfig = this.buildStateStoringConfig();
    this.rebuildColumns();
  }

  /**
   * Column widths are saved per breakpoint. Sharing one key lets a desktop resize restore
   * explicit widths on the same user's phone, which silently defeats adaptive hiding there.
   */
  private buildStateStoringConfig(): Record<string, unknown> {
    const suffix = this.mobileMode ? ':mobile' : this.adaptive ? ':tablet' : '';
    return {
      enabled: this.enableStateStoring,
      type: 'localStorage',
      storageKey: this.storageKey + suffix,
    };
  }

  private rebuildColumns(): void {
    const titled = this.columns.map((col) => titleCaseColumn(col));
    this.titleCasedColumns = this.adaptive ? withHidingPriority(titled) : titled;
  }""")

