"""  @Input() columnHidingEnabled = true;
  /** Desktop selection mode. Selection is always off on phones, where the checkbox column is pure overhead. */
  @Input() selectionMode: 'multiple' | 'single' | 'none' = 'multiple';
  /** When false, tapping a row on a phone goes straight to the parent's edit form instead of the detail sheet. */
  @Input() showDetailOnMobile = true;""")

rep("""  @ViewChild(DxDataGridComponent) private dataGrid?: DxDataGridComponent;

  isDeletePopupVisible = false;
