"""  @ViewChild(DxDataGridComponent) private dataGrid?: DxDataGridComponent;

  isDeletePopupVisible = false;
  selectedRowForDelete: any = null;

  isDetailVisible = false;
  detailRow: any = null;
  detailTitle = 'Record details';
  detailFields: DetailField[] = [];

  constructor(private layout: LayoutService) {
    this.breakpoints.add(
      this.layout.state$.subscribe((state) => {
        this.applyBreakpoint(state.isMobile, state.isOverlay);
        if (!state.isMobile) {
          this.closeDetail();
        }
      }),
    );
  }

  /**
   * On a phone, tapping a row opens the whole record rather than whichever columns happened
   * to survive. It is the only way to reach every field on the inline-editing grids, where
   * DevExtreme turns adaptive hiding off entirely.
   */
  onRowClick(e: any): void {
    if (!this.mobileMode || !this.showDetailOnMobile || e.rowType !== 'data') {
      return;
    }
    // Let the row's own buttons, the adaptive chevron and the checkbox do their job.
    const target = e.event?.target as HTMLElement | undefined;
    if (target?.closest('.dx-command-edit, .dx-command-adaptive, .dx-command-select')) {
      return;
    }
    this.openDetail(e.data);
  }

  private openDetail(row: any): void {
    const fields = this.titleCasedColumns.filter(
      (col) => col && col.type !== 'buttons' && col.dataField,
    );
    this.detailRow = row;
    this.detailFields = fields.map((col) => ({
      label: col.caption || toTitleCase(col.dataField),
      value: formatDetailValue(col, row),
    }));
    this.detailTitle = fields.length ? formatDetailValue(fields[0], row) : 'Record details';
    this.isDetailVisible = true;
  }

  closeDetail(): void {
    this.isDetailVisible = false;
    this.detailRow = null;
    this.detailFields = [];
  }

  editFromDetail(): void {
    const row = this.detailRow;
    this.closeDetail();
    if (row) {
      this.editRow.emit(row);
    }
  }

  deleteFromDetail(): void {
    const row = this.detailRow;
    this.closeDetail();
    if (row) {
      this.selectedRowForDelete = row;
      this.isDeletePopupVisible = true;
    }
  }""")

