rep("""/** What the detail sheet shows for one field. */
export interface DetailField {
  label: string;
  value: string;
}""",
"""/** What the detail sheet shows for one field. */
export interface DetailField {
  label: string;
  value: string;
}

/** Best-effort display value for the detail sheet: honours a column's own calculator and lookup. */
function formatDetailValue(column: any, row: any): string {
  let value = column.calculateCellValue ? column.calculateCellValue(row) : row?.[column.dataField];

  const lookup = column.lookup;
  if (lookup?.dataSource && Array.isArray(lookup.dataSource)) {
    const match = lookup.dataSource.find((item: any) => item?.[lookup.valueExpr] === value);
    if (match) value = match[lookup.displayExpr];
  }

  if (value === null || value === undefined || value === '') return '—';
  if (value instanceof Date) return value.toLocaleDateString();
  if (typeof value === 'boolean') return value ? 'Yes' : 'No';
  return String(value);
}""")

